#!/usr/bin/env python3
"""Single-file BdStomatrix trait extractor.

This distribution artifact embeds the complete audited modular extractor
chain byte-for-byte. At import it verifies every embedded SHA-256 identity,
materializes the sources in a private temporary directory, imports them in the
audited order, and exposes the final v2.5.4 interface. No external extractor
Python file is required at runtime.

The temporary source directory exists only for the current Python process and
is removed automatically. Scientific calculations remain those of the locked
v2.5.4 modules; the output provenance additionally records this single-file
bundle and replaces temporary paths with stable embedded-source identifiers.
"""

