def _decode_and_verify_sources() -> dict[str, bytes]:
    decoded: dict[str, bytes] = {}
    for filename, encoded in _EMBEDDED_SOURCE_PAYLOAD.items():
        data = zlib.decompress(base64.b85decode(encoded.encode("ascii")))
        actual_hash = hashlib.sha256(data).hexdigest()
        expected_hash = _EMBEDDED_SOURCE_SHA256[filename]
        if actual_hash != expected_hash:
            raise RuntimeError(
                "Embedded extractor source hash mismatch for "
                f"{filename}: expected {expected_hash}, observed {actual_hash}."
            )
        decoded[filename] = data
    return decoded


def _load_embedded_extractor_chain() -> tuple[Any, tempfile.TemporaryDirectory[str]]:
    conflicts = [name for name in _RUNTIME_IMPORT_ORDER if name in sys.modules]
    if conflicts:
        raise RuntimeError(
            "The single-file trait extractor must be imported in a fresh "
            "Python process. Conflicting extractor modules: " + ", ".join(conflicts)
        )

    temporary = tempfile.TemporaryDirectory(prefix="bdstomatrix_traits_v254_")
    temporary_root = Path(temporary.name)
    for filename, data in _decode_and_verify_sources().items():
        (temporary_root / filename).write_bytes(data)

    sys.path.insert(0, str(temporary_root))
    try:
        loaded = {
            name: importlib.import_module(name) for name in _RUNTIME_IMPORT_ORDER
        }
    except Exception:
        sys.path.remove(str(temporary_root))
        temporary.cleanup()
        raise

    final_name = "extract_traits_from_pipeline_output_v2_5_4_independent_band_boundary_rules"
    final_module = loaded[final_name]
    # The final installed policy assigns base.__file__ from this module. Point
    # it at the persistent bundled artifact rather than a temporary file.
    final_module.__file__ = str(_OUTER_SCRIPT_PATH)
    return final_module, temporary


_FINAL_MODULE, _TEMPORARY_SOURCE_DIRECTORY = _load_embedded_extractor_chain()
SCRIPT_VERSION = _FINAL_MODULE.SCRIPT_VERSION


def _stable_embedded_path(value: Any) -> Any:
    temporary_prefixes = {
        str(Path(_TEMPORARY_SOURCE_DIRECTORY.name)),
        str(Path(_TEMPORARY_SOURCE_DIRECTORY.name).resolve()),
    }
    if isinstance(value, dict):
        return {key: _stable_embedded_path(item) for key, item in value.items()}
    if isinstance(value, list):
        return [_stable_embedded_path(item) for item in value]
    if isinstance(value, str):
        for temporary_prefix in temporary_prefixes:
            if value.startswith(temporary_prefix):
                filename = Path(value).name
                return f"embedded://trait_extractor.py/{filename}"
    return value


def _record_single_file_provenance(output_dir: Path) -> None:
    provenance_path = output_dir / "trait_extraction_provenance.json"
    provenance = json.loads(provenance_path.read_text(encoding="utf-8"))
    provenance = _stable_embedded_path(provenance)
    provenance["single_file_extractor_bundle"] = {
        "bundle_version": SINGLE_FILE_BUNDLE_VERSION,
        "path": str(_OUTER_SCRIPT_PATH),
        "sha256": hashlib.sha256(_OUTER_SCRIPT_PATH.read_bytes()).hexdigest(),
        "embedded_source_count": len(_EMBEDDED_SOURCE_SHA256),
        "embedded_source_sha256": _EMBEDDED_SOURCE_SHA256,
        "embedded_sources_verified_before_import": True,
        "runtime_materialization": (
            "private temporary directory for this process; automatically removed"
        ),
        "external_trait_extractor_python_dependencies": [],
    }
    provenance_path.write_text(
        json.dumps(provenance, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )

    report_path = output_dir / "TRAIT_EXTRACTION_REPORT.txt"
    if report_path.is_file():
        report = report_path.read_text(encoding="utf-8")
        marker = "Single-file BdStomatrix extractor bundle:"
        if marker not in report:
            report += (
                "\n"
                f"{marker} {SINGLE_FILE_BUNDLE_VERSION}\n"
                "Embedded audited extractor sources were hash-verified before use.\n"
                "No external trait-extractor Python module was required.\n"
            )
            report_path.write_text(report, encoding="utf-8")


def run_trait_extraction() -> Path:
    output_dir = Path(_FINAL_MODULE.run_trait_extraction()).resolve()
    _record_single_file_provenance(output_dir)
    return output_dir


if __name__ == "__main__":
    run_trait_extraction()
